     7→/* ===== Lexer ===== */
     8→
     9→Lexer *lexer_new(const char *input) {
    10→    Lexer *lex = malloc(sizeof(Lexer));
    11→    lex->input = input;
    12→    lex->pos = 0;
    13→    lex->line = 1;
    14→    lex->col = 1;
    15→    return lex;
    16→}
    17→
    18→void lexer_free(Lexer *lex) {
    19→    if (lex) free(lex);
    20→}
    21→
    22→static char lexer_peek(Lexer *lex, int offset) {
    23→    return lex->input[lex->pos + offset];
    24→}
    25→
    26→static void lexer_advance(Lexer *lex) {
    27→    if (lex->input[lex->pos] == '\n') {
    28→        lex->line++;
    29→        lex->col = 1;
    30→    } else {
    31→        lex->col++;
    32→    }
    33→    lex->pos++;
    34→}
    35→
    36→static void lexer_skip_whitespace(Lexer *lex) {
    37→    while (lex->input[lex->pos] && isspace(lex->input[lex->pos])) {
    38→        lexer_advance(lex);
    39→    }
    40→}
    41→
    42→static Token lexer_read_number(Lexer *lex) {
    43→    Token tok = { 0 };
    44→    tok.line = lex->line;
    45→    tok.col = lex->col;
    46→    int start = lex->pos;
    47→
    48→    while (lex->input[lex->pos] && isdigit(lex->input[lex->pos])) {
    49→        lexer_advance(lex);
    50→    }
    51→
    52→    if (lex->input[lex->pos] == '.') {
    53→        tok.kind = TOK_FLOAT;
    54→        lexer_advance(lex);
    55→        while (lex->input[lex->pos] && isdigit(lex->input[lex->pos])) {
    56→            lexer_advance(lex);
    57→        }
    58→        tok.float_value = atof(&lex->input[start]);
    59→    } else {
    60→        tok.kind = TOK_INT;
    61→        tok.int_value = atoll(&lex->input[start]);
    62→    }
    63→
    64→    tok.length = lex->pos - start;
    65→    tok.text = &lex->input[start];
    66→    return tok;
    67→}
    68→
    69→static Token lexer_read_string(Lexer *lex) {
    70→    Token tok = { 0 };
    71→    tok.line = lex->line;
    72→    tok.col = lex->col;
    73→    tok.kind = TOK_STRING;
    74→
    75→    lexer_advance(lex); /* skip opening quote */
    76→    int start = lex->pos;
    77→
    78→    while (lex->input[lex->pos] && lex->input[lex->pos] != '"') {
    79→        if (lex->input[lex->pos] == '\\') {
    80→            lexer_advance(lex);
    81→        }
    82→        lexer_advance(lex);
    83→    }
    84→
    85→    tok.length = lex->pos - start;
    86→    tok.text = &lex->input[start];
    87→
    88→    if (lex->input[lex->pos] == '"') {
    89→        lexer_advance(lex);
    90→    }
    91→
    92→    return tok;
    93→}
    94→
    95→static Token lexer_read_identifier(Lexer *lex) {
    96→    Token tok = { 0 };
    97→    tok.line = lex->line;
    98→    tok.col = lex->col;
    99→    tok.kind = TOK_IDENT;
   100→
   101→    int start = lex->pos;
   102→
   103→    while (lex->input[lex->pos] && (isalnum(lex->input[lex->pos]) || lex->input[lex->pos] == '_')) {
   104→        lexer_advance(lex);
   105→    }
   106→
   107→    tok.length = lex->pos - start;
   108→    tok.text = &lex->input[start];
   109→
   110→    /* Check for keywords */
   111→    if (strncmp(tok.text, "fn", tok.length) == 0 && tok.length == 2) tok.kind = TOK_FN;
   112→    else if (strncmp(tok.text, "return", tok.length) == 0 && tok.length == 6) tok.kind = TOK_RETURN;
   113→    else if (strncmp(tok.text, "if", tok.length) == 0 && tok.length == 2) tok.kind = TOK_IF;
   114→    else if (strncmp(tok.text, "else", tok.length) == 0 && tok.length == 4) tok.kind = TOK_ELSE;
   115→    else if (strncmp(tok.text, "while", tok.length) == 0 && tok.length == 5) tok.kind = TOK_WHILE;
   116→    else if (strncmp(tok.text, "for", tok.length) == 0 && tok.length == 3) tok.kind = TOK_FOR;
   117→    else if (strncmp(tok.text, "in", tok.length) == 0 && tok.length == 2) tok.kind = TOK_IN;
   118→    else if (strncmp(tok.text, "let", tok.length) == 0 && tok.length == 3) tok.kind = TOK_LET;
   119→    else if (strncmp(tok.text, "var", tok.length) == 0 && tok.length == 3) tok.kind = TOK_VAR;
   120→
   121→    return tok;
   122→}
   123→
   124→Token lexer_next(Lexer *lex) {
   125→    lexer_skip_whitespace(lex);
   126→
   127→    if (!lex->input[lex->pos]) {
   128→        Token tok = { TOK_EOF, "", 0, 0, 0, lex->line, lex->col };
   129→        return tok;
   130→    }
   131→
   132→    char ch = lex->input[lex->pos];
   133→
   134→    if (isdigit(ch)) return lexer_read_number(lex);
   135→    if (ch == '"') return lexer_read_string(lex);
   136→    if (isalpha(ch) || ch == '_') return lexer_read_identifier(lex);
   137→
   138→    Token tok = { 0 };
   139→    tok.line = lex->line;
   140→    tok.col = lex->col;
   141→    tok.text = &lex->input[lex->pos];
   142→    tok.length = 1;
   143→
   144→    if (ch == '+') tok.kind = TOK_PLUS;
   145→    else if (ch == '-') {
   146→        lexer_advance(lex);
   147→        if (lex->input[lex->pos] == '>') {
   148→            tok.kind = TOK_ARROW;
   149→            tok.length = 2;
   150→            lexer_advance(lex);
   151→            return tok;
   152→        }
   153→        tok.kind = TOK_MINUS;
   154→        return tok;
   155→    } else if (ch == '*') tok.kind = TOK_STAR;
   156→    else if (ch == '/') tok.kind = TOK_SLASH;
   157→    else if (ch == '%') tok.kind = TOK_PERCENT;
   158→    else if (ch == '=') {
   159→        lexer_advance(lex);
   160→        if (lex->input[lex->pos] == '=') {
   161→            tok.kind = TOK_EQ;
   162→            tok.length = 2;
   163→            lexer_advance(lex);
   164→            return tok;
   165→        }
   166→        tok.kind = TOK_ASSIGN;
   167→        return tok;
   168→    } else if (ch == '!') {
   169→        lexer_advance(lex);
   170→        if (lex->input[lex->pos] == '=') {
   171→            tok.kind = TOK_NE;
   172→            tok.length = 2;
   173→            lexer_advance(lex);
   174→            return tok;
   175→        }
   176→        tok.kind = TOK_NOT;
   177→        return tok;
   178→    } else if (ch == '<') {
   179→        lexer_advance(lex);
   180→        if (lex->input[lex->pos] == '=') {
   181→            tok.kind = TOK_LE;
   182→            tok.length = 2;
   183→            lexer_advance(lex);
   184→            return tok;
   185→        }
   186→        tok.kind = TOK_LT;
   187→        return tok;
   188→    } else if (ch == '>') {
   189→        lexer_advance(lex);
   190→        if (lex->input[lex->pos] == '=') {
   191→            tok.kind = TOK_GE;
   192→            tok.length = 2;
   193→            lexer_advance(lex);
   194→            return tok;
   195→        }
   196→        tok.kind = TOK_GT;
   197→        return tok;
   198→    } else if (ch == '(') tok.kind = TOK_LPAREN;
   199→    else if (ch == ')') tok.kind = TOK_RPAREN;
   200→    else if (ch == '{') tok.kind = TOK_LBRACE;
   201→    else if (ch == '}') tok.kind = TOK_RBRACE;
   202→    else if (ch == '[') tok.kind = TOK_LBRACKET;
   203→    else if (ch == ']') tok.kind = TOK_RBRACKET;
   204→    else if (ch == ',') tok.kind = TOK_COMMA;
   205→    else if (ch == '.') tok.kind = TOK_DOT;
   206→    else if (ch == ':') tok.kind = TOK_COLON;
   207→    else if (ch == ';') tok.kind = TOK_SEMICOLON;
   208→    else if (ch == '&') {
   209→        lexer_advance(lex);
   210→        if (lex->input[lex->pos] == '&') {
   211→            tok.kind = TOK_AND;
   212→            tok.length = 2;
   213→            lexer_advance(lex);
   214→            return tok;
   215→        }
   216→        tok.kind = TOK_ERROR;
   217→        return tok;
   218→    } else if (ch == '|') {
   219→        lexer_advance(lex);
   220→        if (lex->input[lex->pos] == '|') {
   221→            tok.kind = TOK_OR;
   222→            tok.length = 2;
   223→            lexer_advance(lex);
   224→            return tok;
   225→        }
   226→        tok.kind = TOK_ERROR;
   227→        return tok;
   228→    } else {
   229→        tok.kind = TOK_ERROR;
   230→    }
   231→
   232→    lexer_advance(lex);
   233→    return tok;
   234→}
