   236→/* ===== Parser ===== */
   237→
   238→Parser *parser_new(const char *input) {
   239→    Parser *p = malloc(sizeof(Parser));
   240→    p->lexer = lexer_new(input);
   241→    p->current = lexer_next(p->lexer);
   242→    p->peek = lexer_next(p->lexer);
   243→    return p;
   244→}
   245→
   246→void parser_free(Parser *p) {
   247→    if (p) {
   248→        lexer_free(p->lexer);
   249→        free(p);
   250→    }
   251→}
   252→
   253→static void parser_advance(Parser *p) {
   254→    p->current = p->peek;
   255→    p->peek = lexer_next(p->lexer);
   256→}
   257→
   258→static int parser_match(Parser *p, TokenKind kind) {
   259→    return p->current.kind == kind;
   260→}
   261→
   262→static int parser_accept(Parser *p, TokenKind kind) {
   263→    if (parser_match(p, kind)) {
   264→        parser_advance(p);
   265→        return 1;
   266→    }
   267→    return 0;
   268→}
   269→
   270→/* Forward declarations */
   271→static Expr *parse_primary(Parser *p);
   272→static Expr *parse_postfix(Parser *p, Expr *e);
   273→static Expr *parse_unary(Parser *p);
   274→static Expr *parse_multiplicative(Parser *p);
   275→static Expr *parse_additive(Parser *p);
   276→static Expr *parse_comparison(Parser *p);
   277→static Expr *parse_logical_and(Parser *p);
   278→static Expr *parse_logical_or(Parser *p);
   279→static Expr *parse_assignment(Parser *p);
   280→
   281→/* Parse primary expression: literal, variable, (expr) */
   282→static Expr *parse_primary(Parser *p) {
   283→    if (parser_match(p, TOK_INT)) {
   284→        Expr *e = expr_literal_int(p->current.int_value);
   285→        parser_advance(p);
   286→        return e;
   287→    } else if (parser_match(p, TOK_FLOAT)) {
   288→        Expr *e = expr_literal_float(p->current.float_value);
   289→        parser_advance(p);
   290→        return e;
   291→    } else if (parser_match(p, TOK_STRING)) {
   292→        /* Copy string without quotes */
   293→        char str[256];
   294→        strncpy(str, p->current.text, p->current.length);
   295→        str[p->current.length] = '\0';
   296→        Expr *e = expr_literal_string(str);
   297→        parser_advance(p);
   298→        return e;
   299→    } else if (parser_match(p, TOK_IDENT)) {
   300→        char ident[256];
   301→        strncpy(ident, p->current.text, p->current.length);
   302→        ident[p->current.length] = '\0';
   303→        parser_advance(p);
   304→
   305→        Expr *e = expr_var(ident);
   306→        return parse_postfix(p, e);
   307→    } else if (parser_accept(p, TOK_LPAREN)) {
   308→        Expr *e = parse_expression(p);
   309→        parser_accept(p, TOK_RPAREN);
   310→        return e;
   311→    }
   312→
   313→    return expr_literal_int(0); /* error */
   314→}
   315→
   316→static Expr *parse_postfix(Parser *p, Expr *e) {
   317→    /* Handle function calls: name(...) */
   318→    if (parser_match(p, TOK_LPAREN)) {
   319→        /* Get function name from expr */
   320→        if (e->kind != EXPR_VAR) {
   321→            return e;  /* not a function call */
   322→        }
   323→
   324→        const char *func_name = e->var.name;
   325→        parser_advance(p);  /* skip ( */
   326→
   327→        /* Parse arguments */
   328→        Expr **args = malloc(sizeof(Expr *) * 32);
   329→        int arg_count = 0;
   330→
   331→        while (!parser_match(p, TOK_RPAREN) && !parser_match(p, TOK_EOF)) {
   332→            args[arg_count++] = parse_expression(p);
   333→            if (parser_match(p, TOK_COMMA)) {
   334→                parser_advance(p);
   335→            }
   336→        }
   337→
   338→        parser_accept(p, TOK_RPAREN);
   339→
   340→        /* Free the original VAR expr */
   341→        free(e->var.name);
   342→        free(e);
   343→
   344→        /* Return CALL expr */
   345→        return expr_call(func_name, args, arg_count);
   346→    }
   347→
   348→    /* TODO: array indexing, member access */
   349→    return e;
   350→}
   351→
   352→static Expr *parse_unary(Parser *p) {
   353→    if (parser_accept(p, TOK_NOT)) {
   354→        Expr *operand = parse_unary(p);
   355→        return expr_unary(operand, "!");
   356→    } else if (parser_accept(p, TOK_MINUS)) {
   357→        Expr *operand = parse_unary(p);
   358→        return expr_unary(operand, "-");
   359→    }
   360→
   361→    return parse_primary(p);
   362→}
