   364→static Expr *parse_multiplicative(Parser *p) {
   365→    Expr *left = parse_unary(p);
   366→
   367→    while (parser_match(p, TOK_STAR) || parser_match(p, TOK_SLASH)) {
   368→        const char *op = parser_match(p, TOK_STAR) ? "*" : "/";
   369→        parser_advance(p);
   370→        Expr *right = parse_unary(p);
   371→        left = expr_binary(left, right, op);
   372→    }
   373→
   374→    return left;
   375→}
   376→
   377→static Expr *parse_additive(Parser *p) {
   378→    Expr *left = parse_multiplicative(p);
   379→
   380→    while (parser_match(p, TOK_PLUS) || parser_match(p, TOK_MINUS)) {
   381→        const char *op = parser_match(p, TOK_PLUS) ? "+" : "-";
   382→        parser_advance(p);
   383→        Expr *right = parse_multiplicative(p);
   384→        left = expr_binary(left, right, op);
   385→    }
   386→
   387→    return left;
   388→}
   389→
   390→static Expr *parse_comparison(Parser *p) {
   391→    Expr *left = parse_additive(p);
   392→
   393→    while (parser_match(p, TOK_LT) || parser_match(p, TOK_LE) ||
   394→           parser_match(p, TOK_GT) || parser_match(p, TOK_GE) ||
   395→           parser_match(p, TOK_EQ) || parser_match(p, TOK_NE)) {
   396→        const char *op = "?";
   397→        if (parser_match(p, TOK_LT)) op = "<";
   398→        else if (parser_match(p, TOK_LE)) op = "<=";
   399→        else if (parser_match(p, TOK_GT)) op = ">";
   400→        else if (parser_match(p, TOK_GE)) op = ">=";
   401→        else if (parser_match(p, TOK_EQ)) op = "==";
   402→        else if (parser_match(p, TOK_NE)) op = "!=";
   403→
   404→        parser_advance(p);
   405→        Expr *right = parse_additive(p);
   406→        left = expr_binary(left, right, op);
   407→    }
   408→
   409→    return left;
   410→}
   411→
   412→static Expr *parse_logical_and(Parser *p) {
   413→    Expr *left = parse_comparison(p);
   414→
   415→    while (parser_accept(p, TOK_AND)) {
   416→        Expr *right = parse_comparison(p);
   417→        left = expr_binary(left, right, "&&");
   418→    }
   419→
   420→    return left;
   421→}
   422→
   423→static Expr *parse_logical_or(Parser *p) {
   424→    Expr *left = parse_logical_and(p);
   425→
   426→    while (parser_accept(p, TOK_OR)) {
   427→        Expr *right = parse_logical_and(p);
   428→        left = expr_binary(left, right, "||");
   429→    }
   430→
   431→    return left;
   432→}
   433→
   434→static Expr *parse_assignment(Parser *p) {
   435→    Expr *left = parse_logical_or(p);
   436→
   437→    if (parser_accept(p, TOK_ASSIGN)) {
   438→        Expr *right = parse_assignment(p);
   439→        /* For now, create a binary "=" operation (will be code-gen'd as assignment) */
   440→        left = expr_binary(left, right, "=");
   441→    }
   442→
   443→    return left;
   444→}
   445→
   446→Expr *parse_expression(Parser *p) {
   447→    return parse_assignment(p);
   448→}
