   450→Stmt *parse_statement(Parser *p) {
   451→    if (parser_accept(p, TOK_VAR) || parser_accept(p, TOK_LET)) {
   452→        /* Parse variable declaration */
   453→        char name[256];
   454→        strncpy(name, p->current.text, p->current.length);
   455→        name[p->current.length] = '\0';
   456→        parser_advance(p);
   457→
   458→        if (parser_accept(p, TOK_COLON)) {
   459→            /* Skip type annotation (e.g., "i64") */
   460→            if (parser_match(p, TOK_IDENT)) {
   461→                parser_advance(p);
   462→            }
   463→        }
   464→
   465→        Expr *init = NULL;
   466→        if (parser_accept(p, TOK_ASSIGN)) {
   467→            init = parse_expression(p);
   468→        }
   469→
   470→        parser_accept(p, TOK_SEMICOLON);
   471→
   472→        return stmt_var_decl(name, fl_type_i64(), init);
   473→    } else if (parser_accept(p, TOK_IF)) {
   474→        Expr *cond = parse_expression(p);
   475→        Stmt *body = parse_statement(p);
   476→        Stmt *else_body = NULL;
   477→
   478→        if (parser_accept(p, TOK_ELSE)) {
   479→            else_body = parse_statement(p);
   480→        }
   481→
   482→        return stmt_if(cond, body, else_body);
   483→    } else if (parser_accept(p, TOK_WHILE)) {
   484→        Expr *cond = parse_expression(p);
   485→        Stmt *body = parse_statement(p);
   486→        return stmt_while(cond, body);
   487→    } else if (parser_accept(p, TOK_RETURN)) {
   488→        Expr *val = NULL;
   489→        if (!parser_match(p, TOK_SEMICOLON)) {
   490→            val = parse_expression(p);
   491→        }
   492→        parser_accept(p, TOK_SEMICOLON);
   493→        return stmt_return(val);
   494→    } else if (parser_accept(p, TOK_LBRACE)) {
   495→        /* Block statement */
   496→        Stmt **stmts = malloc(sizeof(Stmt *) * 32); /* max 32 statements */
   497→        int count = 0;
   498→
   499→        while (!parser_match(p, TOK_RBRACE) && !parser_match(p, TOK_EOF)) {
   500→            stmts[count++] = parse_statement(p);
   501→        }
   502→
   503→        parser_accept(p, TOK_RBRACE);
   504→
   505→        return stmt_block(stmts, count);
   506→    } else {
   507→        /* Expression statement */
   508→        Expr *e = parse_expression(p);
   509→        parser_accept(p, TOK_SEMICOLON);
   510→        return stmt_expr(e);
   511→    }
   512→}
