   514→FuncDef *parse_function(Parser *p) {
   515→    if (!parser_accept(p, TOK_FN)) {
   516→        return NULL;
   517→    }
   518→
   519→    char name[256] = {0};
   520→    if (parser_match(p, TOK_IDENT)) {
   521→        strncpy(name, p->current.text, p->current.length < 255 ? p->current.length : 255);
   522→        parser_advance(p);
   523→    }
   524→
   525→    parser_accept(p, TOK_LPAREN);
   526→
   527→    /* Parse parameters */
   528→    char **param_names = malloc(sizeof(char *) * 32);
   529→    FlType **param_types = malloc(sizeof(FlType *) * 32);
   530→    int param_count = 0;
   531→
   532→    while (!parser_match(p, TOK_RPAREN) && !parser_match(p, TOK_EOF)) {
   533→        if (parser_match(p, TOK_IDENT)) {
   534→            char pname[256] = {0};
   535→            strncpy(pname, p->current.text, p->current.length < 255 ? p->current.length : 255);
   536→            parser_advance(p);
   537→
   538→            if (parser_accept(p, TOK_COLON)) {
   539→                /* Skip type annotation */
   540→                if (parser_match(p, TOK_IDENT)) {
   541→                    parser_advance(p);
   542→                }
   543→            }
   544→
   545→            param_names[param_count] = strdup(pname);
   546→            param_types[param_count] = fl_type_i64();  /* assume i64 for all params */
   547→            param_count++;
   548→
   549→            if (parser_match(p, TOK_COMMA)) {
   550→                parser_advance(p);
   551→            }
   552→        } else {
   553→            parser_advance(p);  /* skip unknown token */
   554→        }
   555→    }
   556→
   557→    parser_accept(p, TOK_RPAREN);
   558→    parser_accept(p, TOK_ARROW);
   559→
   560→    /* Return type - skip for now */
   561→    if (parser_match(p, TOK_IDENT)) {
   562→        parser_advance(p);
   563→    }
   564→    FlType *ret_type = fl_type_i64();
   565→
   566→    /* Parse body */
   567→    Stmt *body = parse_statement(p);
   568→
   569→    return func_def_new(name, (const char **)param_names, param_types, param_count, ret_type, body);
   570→}
   571→
   572→Program *parse_program(Parser *p) {
   573→    FuncDef **funcs = malloc(sizeof(FuncDef *) * 64); /* max 64 functions */
   574→    int func_count = 0;
   575→
   576→    while (!parser_match(p, TOK_EOF)) {
   577→        if (parser_match(p, TOK_FN)) {
   578→            FuncDef *func = parse_function(p);
   579→            if (func && func_count < 64) {
   580→                funcs[func_count++] = func;
   581→            }
   582→        } else {
   583→            /* Skip unknown tokens */
   584→            parser_advance(p);
   585→        }
   586→    }
   587→
   588→    return program_new(funcs, func_count);
   589→}
